import XCTest
import CryptoKit
@testable import CryptileCore

/// Every test here reads reference/vectors.json (generated by reference/cryptile_ref.py).
/// If a test fails, either the Swift or the Python diverged from the spec — never "fix" by
/// regenerating vectors from Swift output.
final class VectorTests: XCTestCase {
    static let V: [String: Any] = {
        let url = Bundle.module.url(forResource: "vectors", withExtension: "json")!
        return try! JSONSerialization.jsonObject(with: Data(contentsOf: url)) as! [String: Any]
    }()
    var V: [String: Any] { Self.V }
    func S(_ k: String) -> [String: Any] { V[k] as! [String: Any] }
    func sha(_ d: Data) -> String { SHA256.hash(data: d).map { String(format: "%02x", $0) }.joined() }

    let pattern = try! Pattern(grid: 4, cells: [0, 5, 10, 15, 14, 13])
    let deviceSalt = Data((0..<32).map { UInt8($0) })
    let mk = Data(hex: String(repeating: "a1", count: 32))

    func testPatternBytes() {
        XCTAssertEqual(pattern.bytes.hex, S("pattern")["bytes"] as! String)
        XCTAssertThrowsError(try Pattern(grid: 4, cells: [0, 1, 1, 2]))
        XCTAssertThrowsError(try Pattern(grid: 4, cells: [0, 1, 2]))
        XCTAssertThrowsError(try Pattern(grid: 4, cells: [0, 1, 2, 16]))
    }

    func testPatternKeyFast() {
        let v = S("pattern_key_fast")
        let pk = KDF.patternKey(pattern, deviceSalt: deviceSalt, iterations: v["iterations"] as! Int)
        XCTAssertEqual(pk.hex, v["pk"] as! String)
        XCTAssertEqual(KDF.lookupKey(pk).hex, v["k_lookup"] as! String)
        XCTAssertEqual(KDF.wrapKey(pk).hex, v["k_wrap"] as! String)
        XCTAssertEqual(KDF.indexSlotName(lookupKey: KDF.lookupKey(pk)), v["index_slot_name"] as! String)
        // pure Swift PBKDF2 must agree with CommonCrypto
        let pure = PBKDF2.pure(password: pattern.bytes, salt: deviceSalt + Data("cryptile-v1-pattern".utf8),
                               iterations: v["iterations"] as! Int, length: 64)
        XCTAssertEqual(pure.hex, v["pk"] as! String)
    }

    func testPatternKeyCanonical() {
        let v = S("pattern_key_canonical")
        measure {   // performance budget: < 1.5 s on an iPhone 12-class device
            let pk = KDF.patternKey(self.pattern, deviceSalt: self.deviceSalt, iterations: v["iterations"] as! Int)
            XCTAssertEqual(pk.hex, v["pk"] as! String)
        }
    }

    func testSubkeys() {
        let v = S("subkeys")
        XCTAssertEqual(KDF.fileKey(mk).hex, v["file"] as! String)
        XCTAssertEqual(KDF.indexKey(mk).hex, v["index"] as! String)
        XCTAssertEqual(KDF.thumbKey(mk).hex, v["thumb"] as! String)
        XCTAssertEqual(KDF.searchKey(mk).hex, v["search"] as! String)
        XCTAssertEqual(KDF.shareKey(mk).hex, v["share"] as! String)
    }

    func testPadding() throws {
        let cases = V["padding"] as! [[String: Any]]
        let hello = Padding.pad(Data("hello".utf8))
        XCTAssertEqual(hello.count, cases[0]["out_len"] as! Int)
        XCTAssertEqual(sha(hello), cases[0]["out_sha256"] as! String)
        XCTAssertEqual(try Padding.unpad(hello), Data("hello".utf8))
        XCTAssertEqual(Padding.pad(Data(repeating: 0x78, count: Cryptile.padBucket - 1)).count, cases[1]["out_len"] as! Int)
        XCTAssertEqual(Padding.pad(Data(repeating: 0x78, count: Cryptile.padBucket)).count, cases[2]["out_len"] as! Int)
        XCTAssertThrowsError(try Padding.unpad(Data([0, 0, 0])))
    }

    func testSmallBlob() throws {
        let v = S("blob_thumb")
        let blob = try Blob.seal(key: KDF.thumbKey(mk), type: .thumb, plaintext: Data(hex: v["plain"] as! String),
                                 nonce: Data(hex: v["nonce"] as! String))
        XCTAssertEqual(sha(blob), v["blob_sha256"] as! String)
        XCTAssertEqual(blob.prefix(40).hex, v["blob_prefix"] as! String)
        let (t, pt) = try Blob.open(key: KDF.thumbKey(mk), blob: blob)
        XCTAssertEqual(t, .thumb)
        XCTAssertEqual(pt.hex, v["plain"] as! String)
        var bad = blob; bad[25] ^= 1
        XCTAssertThrowsError(try Blob.open(key: KDF.thumbKey(mk), blob: bad)) { XCTAssertEqual($0 as? CryptileError, .authenticationFailed) }
        XCTAssertThrowsError(try Blob.open(key: KDF.fileKey(mk), blob: blob))
    }

    func testFileBlobStream() throws {
        let v = S("file_blob")
        let n = v["plain_len"] as! Int
        let plain = Data((0..<n).map { UInt8(($0 * 7 + 3) & 0xff) })
        XCTAssertEqual(sha(plain), v["plain_sha256"] as! String)
        let blob = try Blob.sealFile(key: KDF.fileKey(mk), plaintext: plain, fileNonce: Data(hex: v["file_nonce"] as! String))
        XCTAssertEqual(blob.count, v["blob_len"] as! Int)
        XCTAssertEqual(sha(blob), v["blob_sha256"] as! String)
        XCTAssertEqual(blob.prefix(48).hex, v["blob_prefix"] as! String)
        XCTAssertEqual(try Blob.openFile(key: KDF.fileKey(mk), blob: blob), plain)
        // truncation to the first chunk must fail (it is re-read as "last" -> aad mismatch)
        let firstChunkEnd = 14 + 4 + Cryptile.chunk + 16
        XCTAssertThrowsError(try Blob.openFile(key: KDF.fileKey(mk), blob: blob.prefix(firstChunkEnd)))
        // empty file
        let e = S("file_blob_empty")
        let empty = try Blob.sealFile(key: KDF.fileKey(mk), plaintext: Data(), fileNonce: Data(hex: v["file_nonce"] as! String))
        XCTAssertEqual(empty.count, e["blob_len"] as! Int)
        XCTAssertEqual(sha(empty), e["blob_sha256"] as! String)
        XCTAssertEqual(try Blob.openFile(key: KDF.fileKey(mk), blob: empty), Data())
    }

    func testRecoveryPhrase() throws {
        let v = S("recovery")
        let rk = Data(hex: v["rk"] as! String)
        XCTAssertEqual(RecoveryPhrase.phrase(from: rk), v["phrase"] as! String)
        XCTAssertEqual(try RecoveryPhrase.recoveryEntropy(from: v["phrase"] as! String), rk)
        XCTAssertEqual(RecoveryPhrase.key(rk: rk, recoverySalt: Data(hex: v["salt"] as! String)).hex, v["k_recovery"] as! String)
        var words = (v["phrase"] as! String).split(separator: " ").map(String.init)
        words[8] = words[8] == "abandon" ? "ability" : "abandon"
        XCTAssertThrowsError(try RecoveryPhrase.recoveryEntropy(from: words.joined(separator: " ")))
        let g = RecoveryPhrase.generate()
        XCTAssertEqual(try RecoveryPhrase.recoveryEntropy(from: g.phrase), g.rk)
    }

    func testIndexBlob() throws {
        let v = S("index_blob")
        let nonces = v["nonces"] as! [String: String]
        let pk = KDF.patternKey(pattern, deviceSalt: deviceSalt, iterations: Cryptile.testIterations)
        let rk = Data(hex: S("recovery")["rk"] as! String)
        let rsalt = Data(hex: S("recovery")["salt"] as! String)
        let entries = [IndexEntry(id: "e1", name: "IMG_0001.heic", mime: "image/heic", size: 123456,
                                  created: 1760000000, blob: "3f2a", thumb: "9c1d")]
        // 1. byte-exact rebuild of the Python blob (proves JSON canonicalization too)
        let blob = try VaultIndex.build(patternKey: pk, masterKey: mk, entries: entries, recoveryEntropy: rk,
                                        recoverySalt: rsalt,
                                        nonces: (Data(hex: nonces["mk"]!), Data(hex: nonces["rec"]!), Data(hex: nonces["index"]!)))
        XCTAssertEqual(blob.count, v["blob_len"] as! Int)
        XCTAssertEqual(sha(blob), v["blob_sha256"] as! String)
        // 2. open the Python-made blob directly
        let python = Data(hex: v["blob_hex"] as! String)
        let opened = try VaultIndex.open(patternKey: pk, blob: python)
        XCTAssertEqual(opened.masterKey, mk)
        XCTAssertEqual(opened.document.entries, entries)
        // 3. recovery phrase alone yields MK
        XCTAssertEqual(try VaultIndex.masterKey(fromPhrase: S("recovery")["phrase"] as! String, document: opened.document), mk)
        // 4. wrong pattern, wrong phrase
        let wrong = KDF.patternKey(try Pattern(grid: 4, cells: [0, 5, 10, 15, 14, 12]), deviceSalt: deviceSalt, iterations: Cryptile.testIterations)
        XCTAssertThrowsError(try VaultIndex.open(patternKey: wrong, blob: python))
        XCTAssertThrowsError(try VaultIndex.masterKey(fromPhrase: RecoveryPhrase.generate().phrase, document: opened.document))
    }

    func testRecoverySlot() throws {
        let v = S("recovery_slot")
        let rk = Data(hex: S("recovery")["rk"] as! String)
        XCTAssertEqual(RecoverySlot.key(rk: rk).hex, v["k_slot"] as! String)
        XCTAssertEqual(RecoverySlot.name(rk: rk), v["name"] as! String)
        // rebuild byte-exactly from the Python-made index document
        let pk = KDF.patternKey(pattern, deviceSalt: deviceSalt, iterations: Cryptile.testIterations)
        let opened = try VaultIndex.open(patternKey: pk, blob: Data(hex: S("index_blob")["blob_hex"] as! String))
        let blob = try RecoverySlot.build(rk: rk, masterKey: mk, document: opened.document, nonce: Data(hex: v["nonce"] as! String))
        XCTAssertEqual(blob.count, v["blob_len"] as! Int)
        XCTAssertEqual(sha(blob), v["blob_sha256"] as! String)
        // open the Python-made slot with the phrase alone
        let rk2 = try RecoveryPhrase.recoveryEntropy(from: S("recovery")["phrase"] as! String)
        let restored = try RecoverySlot.open(rk: rk2, blob: Data(hex: v["blob_hex"] as! String))
        XCTAssertEqual(restored.masterKey, mk)
        XCTAssertEqual(restored.document, opened.document)
        XCTAssertThrowsError(try RecoverySlot.open(rk: RecoveryPhrase.generate().rk, blob: blob))
    }

    func testContainerShape() {
        XCTAssertEqual(ContainerShape.totalIndexSlots(real: 0), Cryptile.minIndexSlots)
        XCTAssertEqual(ContainerShape.totalIndexSlots(real: 1), Cryptile.minIndexSlots)
        XCTAssertEqual(ContainerShape.totalIndexSlots(real: 6), 12)
        let d = ContainerShape.decoyBlob()
        XCTAssertEqual(d.prefix(4), Cryptile.magic)
        XCTAssertEqual((d.count - 6 - 12 - 16) % Cryptile.padBucket, 0)
        XCTAssertEqual(ContainerShape.decoySlotName().count, 32)
    }
}
